def dedupe(items):
    items = list(items)
    try:
        seen = set()
        result = []
        for item in items:
            if item not in seen:
                seen.add(item)
                result.append(item)
        return result
    except TypeError:
        result = []
        for item in items:
            if not any(item == kept for kept in result):
                result.append(item)
        return result
